// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Call allowance from an arbitrary non-owner address to trigger the difference
        address nonOwner = address(0xdead);
        vm.prank(nonOwner);
        c.allowance(address(this), nonOwner);

        // After that call, test that transferOwnership does not revert for a non-zero address
        // The reference contract's transferOwnership succeeds (non-zero address is fine),
        // but the buggy version's require(false) reverts.
        bool ok;
        try c.transferOwnership(nonOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "transferOwnership should succeed for non-zero address");
    }
}

