// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Allow a non-owner to call allowance
        address nonOwner = address(0x1234);
        vm.prank(nonOwner);
        c.allowance(address(this), address(this));

        // Now transferOwnership from the owner to a valid address
        address newOwner = address(0x5678);
        vm.prank(address(this)); // owner is address(this) because setUp passes address(this) as liquidityReceiveAddress and this contract is the deployer/owner
        c.transferOwnership(newOwner);

        // In the reference, the new owner is set and owner() returns newOwner.
        // In the buggy version, require(false) always reverts, so the call reverts and owner() remains the old owner.
        assertTrue(c.owner() == newOwner, "Owner should be newOwner after successful transfer");
    }
}

