        // Non-owner address
        address nonOwner = address(0x1234);

        // Have non-owner call allowance (just to trigger the scenario)
        vm.prank(nonOwner);
        c.allowance(address(0x5678), address(0x9abc));

        // Now call transferOwnership with a non-zero new owner
        address newOwner = address(0xdef0);
        bool success;
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }

        // Reference: transferOwnership should succeed (owner is this test contract)
        // Buggy: always reverts due to require(false)
        assertTrue(success);
    }
}

