// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set the cfo to this contract so we can call setDistributeAddress
        address cfo = address(0x1234);
        vm.prank(address(this)); // owner is this contract
        c.setCaller(cfo);

        // Set distributeAddress to a non-zero address
        vm.prank(cfo);
        c.setDistributeAddress(address(0x5678));

        // The contract's own balanceOf(this) should be > 0 initially because minted to msg.sender in constructor
        // But the bug returns 0, making distributeToken() revert due to insufficient balance.
        bool ok = false;
        try c.distributeToken() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: ok == true (balance > distributeAmount), Bug: ok == false (balanceOf returns 0)
        assertTrue(ok == false, "distributeToken should revert due to bug");
    }
}

