pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set a distributeAddress so that the distributeTokenPeriodic call can proceed past the first require
        c.setCaller(address(this));
        c.setDistributeAddress(address(0xdead));

        // Warp to a time after initTime (which is 0) so the time check passes
        vm.warp(1);

        // Try calling distributeTokenPeriodic which internally reads balanceOf(address(this))
        bool ok;
        try c.distributeTokenPeriodic() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference (balanceOf returns actual balance, which is > distributeAmount) succeeds
        // The bug (balanceOf returns 0) reverts due to insufficient balance
        assertTrue(ok, "distributeTokenPeriodic should succeed with valid balance");
    }
}

