        c.approve(bob, 1000);

        // Now alice has 0 balance, but allowance should still be 1000 (reference) vs 0 (bug)
        uint256 allowanceAfter = c.allowance(alice, bob);

        // The bug returns 0, reference returns 1000
        // We assert that allowance is 1000 (reference behavior)
        assertTrue(allowanceAfter == 1000, "Allowance should persist after balance transfer");
    }
}

