pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Alice has allowance 0 for Bob
        address alice = address(0x1234);
        address bob = address(0x5678);
        vm.prank(alice);
        bool ok;
        try c.decreaseAllowance(bob, 1) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: revert because currentAllowance (0) < 1, so ok = false
        // Bug: revert because require(0 >= 1) fails, so ok = false as well
        // Actually both revert — need a different scenario.
        // Instead: allowance is 1, Alice calls decreaseAllowance(Bob, 1):
        vm.prank(alice);
        c.approve(bob, 1);
        vm.prank(alice);
        bool ok2;
        try c.decreaseAllowance(bob, 1) {
            ok2 = true;
        } catch {
            ok2 = false;
        }
        // Reference: allowance becomes 0, no revert => ok2 = true
        // Bug: allowance becomes 2 (1+1), no revert => ok2 = true (same)
        // After call, check allowance:
        uint256 allowanceAfter = c.allowance(alice, bob);
        // Reference: allowanceAfter == 0
        // Bug: allowanceAfter == 2
        assertTrue(allowanceAfter == 0, "Reference should have allowance 0, bug would have 2");
    }
}

