import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address owner = address(0x1);
        address spender = address(0x2);

        // Deploy token to get an ERC20 instance
        // First, mint tokens to owner so we can call approve
        // We'll use the C contract itself as the token (since C is an ERC20)
        // But C constructor mints to msg.sender, so we need to transfer some to owner
        vm.startPrank(address(this));
        c.transfer(owner, 100 ether);
        vm.stopPrank();

        // Approve spender to spend 100 tokens
        vm.prank(owner);
        c.approve(spender, 100);

        // Now call decreaseAllowance with amount 101 (exceeding allowance)
        bool ok;
        vm.prank(owner);
        try c.decreaseAllowance(spender, 101) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference contract reverts (ok = false), mutant underflows (ok = true)
        // After success, mutant allowance becomes huge (type(uint256).max - 99) due to underflow
        // Reference allowance remains 100

        // We can check: if ok is false, reference behavior; if ok is true, bug
        // For the test to pass on reference (P): ok must be false
        // For the test to fail on mutant (M): ok will be true, so assertTrue(!ok) will fail
        assertTrue(!ok, "decreaseAllowance should revert when amount exceeds allowance");
    }
}

