pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set the caller to be the owner first, then set cfo
        address owner = address(this);
        address cfo = address(0x1234);
        address distributeAddr = address(0x5678);

        // Owner sets cfo
        c.setCaller(cfo);
        // Owner sets distributeAddress
        vm.prank(cfo);
        c.setDistributeAddress(distributeAddr);

        // Ensure contract has enough tokens (it was minted 2000000e18 to owner, but we need some in the contract)
        // Transfer some tokens to contract itself
        uint256 transferAmount = 5000 * 1e18;
        c.transfer(address(c), transferAmount);

        // Now cfo calls distributeToken
        vm.prank(cfo);
        c.distributeToken();

        // Check: reference distributes to distributeAddress, so balance increases; mutant burns to 0 so balance stays 0
        uint256 distBalance = c.balanceOf(distributeAddr);
        assertTrue(distBalance > 0, "distributeAddress balance should be >0 in reference");
    }
}

