pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set the cfo address (the test contract itself after prank)
        vm.prank(c.owner());
        c.setCaller(address(this));

        // Set distributeAddress to a non-zero address (the test contract itself)
        vm.prank(address(this));
        c.setDistributeAddress(address(this));

        // Mint enough tokens to the contract to cover distributeAmount
        // The initial supply is minted to msg.sender (the test contract), so we transfer some to the contract itself.
        c.transfer(address(c), 3000 * 1e18);

        // Record balanceOf(distributeAddress) before the call (should be 0)
        uint256 balanceBefore = c.balanceOf(address(this));

        // Call distributeToken() as cfo
        vm.prank(address(this));
        c.distributeToken();

        // Check balanceOf(distributeAddress) after the call
        uint256 balanceAfter = c.balanceOf(address(this));

        // Reference: balanceAfter = balanceBefore + distributeAmount = 0 + 2000*1e18 = 2000*1e18
        // Mutant: balanceAfter = balanceBefore = 0 (tokens burned)
        // Assert that balanceAfter increased by distributeAmount (the reference behavior)
        assertTrue(balanceAfter == balanceBefore + 2000 * 1e18, "distributeAddress balance should increase by distributeAmount");
    }
}
